'use strict';

const $ = id => document.getElementById(id);
const state = {
  view: 'workspace', paused: false, runId: null, runs: [], snapshot: null, control: null,
  providers: null, endpoints: null, agents: null, artifacts: [], priorSnapshot: null, signalMessages: [], changedTasks: new Map(), memoryPulseUntil: 0,
  deep: 'panorama', stream: null, selectedTemplate: null,
};
const titles = {
  workspace:['USER WORKSPACE','工作台'], tasks:['RUN PROGRESS','任务进度'], agents:['ADVANCED AGENT STUDIO','智能体'],
  deliverables:['DELIVERABLES','结果与文件'], settings:['SETTINGS','设置'], observatory:['TECH OBSERVATORY','协作运行'],
  lab:['TECH VALIDATION','验证实验'], judge:['TECHNICAL TRANSPARENCY','技术透视'], lineage:['TRACEABILITY','数据血缘']
};

function esc(v){return String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function short(v,n=36){const s=String(v??'—');return s.length>n?s.slice(0,n-1)+'…':s;}
function num(v,d=0){return Number.isFinite(Number(v))?Number(v).toLocaleString(undefined,{maximumFractionDigits:d,minimumFractionDigits:d}):'—';}
function pct(v){return Number.isFinite(Number(v))?`${(Number(v)*100).toFixed(1)}%`:'—';}
function ts(v){if(!v)return '—';const n=Number(v);const d=Number.isFinite(n)?new Date(n*1000):new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleString();}
function statusClass(v){const s=String(v||'').toUpperCase();if(['SUCCEEDED','VERIFIED','APPLIED','READY'].includes(s))return'ok';if(['FAILED','REJECTED','FAILED_TO_START'].includes(s))return'fail';if(['RUNNING','VERIFYING','QUEUED','STOPPING','PLANNED'].includes(s))return'run';return'neutral';}
function statePill(v){return `<span class="state-pill ${statusClass(v)}">${esc(v||'UNKNOWN')}</span>`;}
function readyRow(name,ok,value,kind){const cls=kind||((ok===true)?'ok':(ok===false)?'bad':'warn');const icon=ok===true?'✓':ok===false?'!':'·';return `<div class="ready-row"><div class="ready-name"><span class="ready-icon ${cls}">${icon}</span>${esc(name)}</div><div class="ready-value">${esc(value)}</div></div>`;}
function detailRow(name,value){return `<div class="detail-row"><span>${esc(name)}</span><span>${esc(value)}</span></div>`;}
function metricCell(name,value,note=''){return `<div class="metric-cell"><span>${esc(name)}</span><strong>${esc(value)}</strong>${note?`<small>${esc(note)}</small>`:''}</div>`;}
function truthRow(name,value){return `<div class="truth-row"><span>${esc(name)}</span><strong>${esc(value)}</strong></div>`;}

function authModeLabel(mode){const m=String(mode||'unclassified');const map={real_api:'REAL API',real_api_unverified_provider:'REAL API',api_test_endpoint:'TEST API',remote_rpc:'REMOTE RPC',mock:'MOCK',unbound:'UNBOUND',test_fixture:'TEST FIXTURE'};return map[m]||m.toUpperCase();}
function authModeClass(mode){const m=String(mode||'');if(m==='real_api'||m==='real_api_unverified_provider'||m==='remote_rpc')return'ok';if(['mock','unbound','test_fixture','api_test_endpoint'].includes(m))return'fail';return'warn';}
function buttonBusy(button,busy,label){if(!button)return;if(busy){button.dataset.idleLabel=button.textContent;button.textContent=label||'处理中…';button.disabled=true;}else{button.textContent=button.dataset.idleLabel||button.textContent;button.disabled=false;delete button.dataset.idleLabel;}}
function toast(message,fail=false){const el=$('toast');el.textContent=message;el.style.background=fail?'#8d2638':'#17191e';el.classList.remove('hidden');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.add('hidden'),3200);}

async function fetchJSON(url,options){const r=await fetch(url,{cache:'no-store',...options});let data={};try{data=await r.json();}catch(_){data={};}if(!r.ok)throw new Error(data.message||data.error||`HTTP ${r.status}`);return data;}
async function postJSON(url,payload){return fetchJSON(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload||{})});}

function setView(view){if(!titles[view])return;state.view=view;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('pageEyebrow').textContent=titles[view][0];$('pageTitle').textContent=titles[view][1];if(view==='deliverables')loadArtifacts();if(view==='settings'||view==='agents'){loadSettingsBase().then(()=>renderCurrentView()).catch(()=>{});}else{renderCurrentView();}window.scrollTo({top:0,behavior:'smooth'});}

function compareSnapshots(next){const prev=state.snapshot;if(!prev){state.priorSnapshot=null;return;}
  state.priorSnapshot=prev;
  const oldMessages=new Set((prev.communication?.items||[]).map(x=>x.message_id).filter(Boolean));
  const now=Date.now();
  for(const item of next.communication?.items||[]){if(item.policy_action==='SEND'&&item.message_id&&!oldMessages.has(item.message_id)){state.signalMessages.push({...item,expires:now+2600});}}
  state.signalMessages=state.signalMessages.filter(x=>x.expires>now);
  const oldStates=new Map((prev.task_graph?.nodes||[]).map(x=>[x.id,x.status]));
  for(const node of next.task_graph?.nodes||[]){if(oldStates.has(node.id)&&oldStates.get(node.id)!==node.status)state.changedTasks.set(node.id,now+1700);}
  for(const [id,until] of [...state.changedTasks])if(until<now)state.changedTasks.delete(id);
  const oldP=Number(prev.memory?.context_pack_count||0), newP=Number(next.memory?.context_pack_count||0);if(newP>oldP)state.memoryPulseUntil=now+2200;
}

async function loadRuntimeBase(){
  const [runs,control]=await Promise.all([fetchJSON('/api/runs').catch(()=>[]),fetchJSON('/api/control/status').catch(()=>null)]);
  state.runs=Array.isArray(runs)?runs:[];state.control=control;if(!state.runId&&state.runs.length)state.runId=state.runs[0].run_id;renderRunSelector();
}
async function loadSettingsBase(){
  const [providers,endpoints,agents]=await Promise.all([fetchJSON('/api/settings/providers').catch(()=>null),fetchJSON('/api/settings/endpoints').catch(()=>null),fetchJSON('/api/settings/agents').catch(()=>null)]);
  state.providers=providers;state.endpoints=endpoints;state.agents=agents;
}
async function loadBase(){await Promise.all([loadRuntimeBase(),loadSettingsBase()]);}
async function loadSnapshot(){
  const suffix=state.runId?`?run_id=${encodeURIComponent(state.runId)}`:'';
  try{const snap=await fetchJSON(`/api/snapshot${suffix}`);compareSnapshots(snap);state.snapshot=snap;$('waiting').classList.add('hidden');}
  catch(_){state.snapshot=null;$('waiting').classList.remove('hidden');}
}
async function loadLog(){const job=state.control?.active_job;if(!job){$('jobLog').textContent='暂无活动任务';return;}try{const data=await fetchJSON(`/api/control/log?job_id=${encodeURIComponent(job.job_id)}`);$('jobLog').textContent=data.log_tail||'任务已启动，暂时还没有日志输出。';}catch(e){$('jobLog').textContent=`日志读取失败：${e.message}`;}}
async function refresh(){if(state.paused)return;try{await loadRuntimeBase();await loadSnapshot();if(state.view==='tasks')await loadLog();renderCurrentView();}catch(e){toast(`刷新失败：${e.message}`,true);}}

function renderRunSelector(){const el=$('runSelector');const current=state.runId;el.innerHTML=state.runs.length?state.runs.map(r=>`<option value="${esc(r.run_id)}">${esc(short(r.run_id,30))}</option>`).join(''):'<option value="">暂无运行</option>';if(current&&state.runs.some(r=>r.run_id===current))el.value=current;}
function renderChrome(){const snap=state.snapshot,control=state.control,run=snap?.run;let label='系统空闲',cls='idle';if(control?.active_job?.status==='RUNNING'){label='任务正在运行';cls='run';}else if(run?.status==='SUCCEEDED'){label='最近运行成功';cls='ok';}else if(run?.status==='FAILED'){label='最近运行失败';cls='fail';}$('sidebarStatus').innerHTML=`<span class="status-dot ${cls}"></span>${esc(label)}`;$('lastUpdate').textContent=snap?.generated_at?`快照 ${ts(snap.generated_at)}`:'尚未取得运行快照';}

function renderReadiness(target){if(!target||!state.control)return;const e=state.control.environment||{};target.innerHTML=[readyRow('模型服务',e.provider_configured,e.provider_configured?`${e.provider_name} · ${e.model}`:'未配置'),readyRow('API Key',e.api_key_required?e.api_key_present:true,e.api_key_required?(e.api_key_present?'已由后端保存':'缺失'):'该服务无需 Key'),readyRow('OR-Tools',e.ortools_importable,e.ortools_importable?'可用':'缺失')].join('');}
function renderWorkspace(){const c=state.control||{},e=c.environment||{},snap=state.snapshot,run=snap?.run,meta=snap?.runtime_metadata||{},auth=snap?.authenticity||{},exec=snap?.execution||{};$('providerMini').textContent=e.provider_configured?`${e.provider_name} · ${e.model}`:'模型服务未配置';renderReadiness($('readinessList'));
  const scenarios=c.scenarios||[];$('templateCards').innerHTML=scenarios.map(x=>`<div class="template-card ${state.selectedTemplate===x.id?'selected':''}"><strong>${esc(x.name)}</strong><p>${esc(x.description)}</p><button type="button" class="text-button" data-use-template="${esc(x.id)}">使用此模板 →</button></div>`).join('')||'<div class="subtle">暂无模板</div>';
  $('templateCards').querySelectorAll('[data-use-template]').forEach(b=>b.onclick=()=>applyTaskTemplate(scenarios.find(x=>x.id===b.dataset.useTemplate)));
  renderTemplatePreview(scenarios.find(x=>x.id===state.selectedTemplate));
  $('recentRunsMini').innerHTML=state.runs.slice(0,4).map(r=>`<div class="mini-run"><div class="mini-run-top"><strong>${esc(short(r.run_id,25))}</strong>${statePill(r.status)}</div><span>${esc(r.phase||'—')} · ${ts(r.generated_at)}</span></div>`).join('')||'<div class="subtle">暂无运行</div>';
  const truth=$('authenticityMini');if(truth){truth.innerHTML=snap?[`<div class="truth-mini ${auth.competition_strict_real_agent?'ok':'warn'}"><span>Agent 真实性</span><strong>${esc(auth.verdict||'未判定')}</strong></div>`,`<div class="truth-mini"><span>API 请求</span><strong>${num(auth.api_usage?.request_count,0)}</strong></div>`,`<div class="truth-mini"><span>真实工具执行</span><strong>${num(exec.successful_concrete_tool_call_count,0)}</strong></div>`,`<div class="truth-mini"><span>已分配 Agent</span><strong>${num(auth.assigned_agent_count,0)}</strong></div>`].join(''):'<div class="truth-mini warn"><span>真实性</span><strong>等待真实 Run</strong></div>';}
  renderWorkspacePipeline(run,snap);
  updateActionAvailability();
  if(!snap){$('currentWorkEmpty').classList.remove('hidden');$('currentWorkBody').classList.add('hidden');$('currentRunStatus').className='state-pill neutral';$('currentRunStatus').textContent='IDLE';return;}
  $('currentWorkEmpty').classList.add('hidden');$('currentWorkBody').classList.remove('hidden');$('currentRunStatus').className=`state-pill ${statusClass(run.status)}`;$('currentRunStatus').textContent=run.status;$('currentRunId').textContent=run.run_id;$('currentObjective').textContent=meta.objective||'当前复杂任务';const total=Number(run.task_count||0),done=Number(run.succeeded||0);$('currentProgress').textContent=total?`${Math.round(done/total*100)}%`:'—';renderPhaseRail(run);renderWorkflowTelemetry();renderLiveAction();}
function applyTaskTemplate(t){if(!t)return;state.selectedTemplate=t.id;$('goalInput').value=t.template_goal||t.description||'';renderTemplatePreview(t);updateActionAvailability();$('goalInput').focus();toast('模板已填入任务目标，可继续修改后再启动');}
function renderTemplatePreview(t){const el=$('templatePreview');if(!el)return;if(!t){el.classList.add('hidden');el.innerHTML='';return;}const req=t.requirements||[],out=t.deliverables||[];el.classList.remove('hidden');el.innerHTML=`<div class="template-preview-head"><strong>${esc(t.name)}</strong><button type="button" class="text-button" id="clearTemplateBtn">清除</button></div><span>执行要求</span><ul>${req.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><span>预期交付</span><ul>${out.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><small>模板只负责填充任务；只有点击“开始任务”才会提交统一执行链。</small>`;const clear=$('clearTemplateBtn');if(clear)clear.onclick=()=>{state.selectedTemplate=null;$('goalInput').value='';renderTemplatePreview(null);updateActionAvailability();};}
function renderWorkspacePipeline(run,snap){const el=$('workspacePipeline');if(!el)return;const nodes=[['01','目标','GoalSpec','goalspec'],['02','拆解','Task DAG','dag'],['03','协同','API Agents','agents'],['04','执行','ToolRuntime','tools'],['05','验证','Evidence','verify']];let active=0;if(run?.status==='SUCCEEDED')active=5;else if(snap){const taskCount=Number(run?.task_count||0),running=Number(run?.running||0),verified=Number(run?.verified_task_count||0),concrete=Number(snap.execution?.successful_concrete_tool_call_count||0);if(taskCount>0)active=2;if(running>0||Number(run?.succeeded||0)>0)active=3;if(concrete>0)active=4;if(verified>0)active=4;}
  el.innerHTML=nodes.map((n,i)=>`<div class="pipeline-node ${i<active?'done':i===active&&snap?'active':''}"><span class="pipeline-index">${n[0]}</span><div><strong>${n[1]}</strong><small>${n[2]}</small></div>${i<nodes.length-1?'<span class="pipeline-arrow">→</span>':''}</div>`).join('');}
function updateActionAvailability(){const start=$('startCustomBtn'),stop=$('stopJobBtn'),goal=$('goalInput')?.value.trim()||'',env=state.control?.environment||{},active=state.control?.active_job;const ready=Boolean(env.provider_configured&&env.ortools_importable);if(start){start.disabled=goal.length<8||active?.status==='RUNNING';start.title=goal.length<8?'任务目标至少 8 个字符':active?.status==='RUNNING'?'已有任务正在运行':(ready?'启动真实后端任务':'启动任务（将根据环境状态提示配置问题）');}if(stop){stop.disabled=!active||!['RUNNING','QUEUED','STOPPING'].includes(active.status);}}
function renderPhaseRail(run){const phases=['理解目标','规划任务','协同执行','验证结果','完成交付'];const total=Number(run.task_count||0),done=Number(run.succeeded||0);let idx=0;if(run.status==='SUCCEEDED')idx=4;else if(run.status==='FAILED')idx=3;else if(Number(run.running||0)>0)idx=2;else if(Number(run.ready||0)>0)idx=1;else if(total>0)idx=Math.min(3,Math.floor(done/Math.max(total,1)*4));$('phaseRail').innerHTML=phases.map((p,i)=>`<div class="phase-step-wrap"><div class="phase-node ${i<idx?'done':i===idx&&run.status!=='SUCCEEDED'?'active':run.status==='SUCCEEDED'?'done':''}"></div><span class="phase-label">${p}</span>${i<phases.length-1?`<div class="phase-line ${i<idx?'done':''}"></div>`:''}</div>`).join('');}
function renderWorkflowTelemetry(){const el=$('workflowTelemetry');if(!el)return;const s=state.snapshot||{},r=s.run||{},nodes=s.task_graph?.nodes||[],events=s.events||[];const active=nodes.find(n=>['RUNNING','VERIFYING'].includes(String(n.status)))||nodes.find(n=>String(n.status)==='READY');const assigned=active?.assignment?.agent_id||null;const tier=active?.assignment?actualTier(active.assignment).toUpperCase():null;const toolEvents=events.filter(e=>eventType(e)==='TOOL_EXECUTED');const concrete=toolEvents.map(e=>e.payload?.tool_call?.tool_name).filter(x=>x&&x!=='task');const verified=events.filter(e=>eventType(e)==='TASK_VERIFIED').length;const messages=Number(s.communication?.total??(s.communication?.items||[]).length);const packs=Number(s.memory?.context_pack_count||0);const status=String(r.status||'');el.innerHTML=[
  `<div class="telemetry-card"><span>当前执行</span><strong>${status==='SUCCEEDED'||status==='FAILED'?'无活动 Agent':esc(assigned||'等待调度')}</strong><small>${status==='SUCCEEDED'||status==='FAILED'?'Run 已结束':tier?`Tier · ${esc(tier)}`:'尚未分配执行层'}</small></div>`,
  `<div class="telemetry-card"><span>具体工具</span><strong>${concrete.length?esc(short(concrete.at(-1),28)):'未发生'}</strong><small>${concrete.length?`${concrete.length} concrete tool event(s)`:'Agent reasoning 不冒充外部工具'}</small></div>`,
  `<div class="telemetry-card"><span>协作通信</span><strong>${num(messages,0)}</strong><small>MessagePolicy decisions</small></div>`,
  `<div class="telemetry-card"><span>记忆唤醒</span><strong>${num(packs,0)}</strong><small>ContextPacks</small></div>`,
  `<div class="telemetry-card"><span>独立验证</span><strong>${num(verified,0)}</strong><small>TASK_VERIFIED</small></div>`
].join('');}
function renderLiveAction(){const snap=state.snapshot,run=snap?.run;if(!snap)return;const nodes=snap.task_graph?.nodes||[];const active=nodes.find(n=>['RUNNING','VERIFYING'].includes(n.status))||nodes.find(n=>n.status==='READY');const el=$('liveAction');if(run.status==='RUNNING'&&active){el.innerHTML=`<span class="pulse-dot"></span><span>${esc(active.status==='VERIFYING'?'正在验证':active.status==='READY'?'等待调度':'正在执行')}：${esc(short(active.label,70))}</span>`;}else if(run.status==='SUCCEEDED'){el.innerHTML=`<span class="ready-icon ok">✓</span><span>任务链已完成，证据 ${num(run.evidence_count,0)} 项</span>`;}else if(run.status==='FAILED'){el.innerHTML=`<span class="ready-icon bad">!</span><span>运行失败，请在技术观测/Trace 中查看真实原因</span>`;}else{el.textContent='当前没有运行中的任务节点';}}

function renderTasks(){const taskJobs=state.control?.task_jobs||[],taskRuns=state.runs||[];const snap=state.snapshot,run=snap?.run,graph=snap?.task_graph||{},nodes=graph.nodes||[],edges=graph.edges||[];
  $('runHistory').innerHTML=taskRuns.length?taskRuns.map(r=>`<button type="button" class="run-item ${r.run_id===state.runId?'selected':''}" data-run="${esc(r.run_id||'')}"><div class="run-item-top"><strong>${esc(short(r.run_id||'Task Run',34))}</strong>${statePill(r.status)}</div><div class="run-item-sub"><span>${esc(r.phase||'authoritative snapshot')}</span><span>${ts(r.generated_at)}</span></div></button>`).join(''):'<div class="empty-state"><strong>暂无任务记录</strong><span>列表来自 /api/runs 的 authoritative snapshots；Benchmark 与故障实验使用隔离 workspace，不会混入这里。</span></div>';
  $('runHistory').querySelectorAll('[data-run]').forEach(el=>el.onclick=()=>{if(el.dataset.run){state.runId=el.dataset.run;refresh();}});
  const active=state.control?.active_job;const selectedJob=taskJobs.find(j=>j.run_id===state.runId)||((active&&['custom_task','scenario','remote_endpoint_acceptance'].includes(active.kind))?active:null);
  const badge=run?.status||selectedJob?.status||'IDLE';$('activeJobBadge').className=`state-pill ${statusClass(badge)}`;$('activeJobBadge').textContent=badge;
  $('activeJob').innerHTML=run?[detailRow('Run ID',run.run_id),detailRow('状态',run.status),detailRow('任务节点',`${run.succeeded||0}/${run.task_count||0} 成功`),detailRow('验证',`${run.verified_task_count||0}/${run.task_count||0}`),detailRow('Evidence',run.evidence_count||0),detailRow('数据来源','authoritative snapshot + EventStore')].join(''):selectedJob?[detailRow('任务',selectedJob.label),detailRow('Run ID',selectedJob.run_id||'—'),detailRow('状态',selectedJob.status),detailRow('开始时间',ts(selectedJob.started_at)),detailRow('状态来源','后端 subprocess 生命周期')].join(''):[detailRow('状态','IDLE'),detailRow('状态来源','当前没有可展示的 Task Run')].join('');
  const summary=$('taskRunSummary');if(summary)summary.innerHTML=[metricCell('Tasks',num(run?.task_count||nodes.length,0),'authoritative DAG nodes'),metricCell('Succeeded',num(run?.succeeded||nodes.filter(n=>n.status==='SUCCEEDED').length,0),'verified completion'),metricCell('Running',num(run?.running||nodes.filter(n=>n.status==='RUNNING').length,0),'current execution'),metricCell('Evidence',num(run?.evidence_count||0,0),'content-addressed')].join('');
  renderTaskRuntimeGraph(nodes,edges);
}
function renderTaskRuntimeGraph(nodes,edges){const el=$('taskRuntimeGraph'),ins=$('taskRuntimeInspector'),meta=$('taskGraphMeta');if(!el||!ins||!meta)return;meta.textContent=`${nodes.length} tasks · ${edges.length} dependencies`;if(!nodes.length){el.innerHTML=deepEmpty('等待任务图','选择一个 Task Run 后显示真实 DAG。');ins.innerHTML=deepEmpty('Task Inspector','点击任务节点查看 Assignment 与 Evidence。');return;}const byId=new Map(nodes.map(n=>[String(n.id),n]));const preds=new Map(nodes.map(n=>[String(n.id),[]]));edges.forEach(e=>{if(preds.has(String(e.target)))preds.get(String(e.target)).push(String(e.source))});el.innerHTML=nodes.map(n=>`<button type="button" class="task-flow-node ${statusClass(n.status)}" data-task-runtime="${esc(n.id)}"><span>${esc(n.status||'UNKNOWN')}</span><strong>${esc(short(n.label||n.id,42))}</strong><small>${esc(short(n.assignment?.agent_id||'未分配',30))}</small></button>`).join('<span class="task-inline-arrow">→</span>');const show=n=>{const evs=deepEventsFor(n.id),verify=evs.filter(e=>eventType(e)==='TASK_VERIFIED').at(-1),toolEvents=evs.filter(e=>eventType(e)==='TOOL_EXECUTED'),concrete=toolEvents.map(e=>e.payload?.tool_call?.tool_name).filter(x=>x&&x!=='task'),evidence=verify?.payload?.evidence_ids||[];ins.innerHTML=`<h4 class="inspector-title">${esc(n.label||n.id)}</h4><p class="inspector-sub">${esc(n.id)} · ${esc(n.status||'UNKNOWN')}</p><div class="inspector-block"><span>Dependencies</span><strong>${esc((preds.get(String(n.id))||[]).join(', ')||'ROOT')}</strong></div><div class="inspector-block"><span>Agent / Tier</span><strong>${esc(n.assignment?.agent_id||'未分配')} · ${esc(n.assignment?actualTier(n.assignment).toUpperCase():'—')}</strong></div><div class="inspector-block"><span>Concrete Tool</span><code>${esc(concrete.join(', ')||'未发生具体外部工具执行')}</code></div><div class="inspector-block"><span>Verifier</span><strong>${verify?.payload?.passed===true?'PASS':verify?.payload?.passed===false?'FAIL':'等待'}</strong></div><div class="inspector-block"><span>Evidence</span><code>${esc(evidence.join(', ')||'尚无')}</code></div>`;};el.querySelectorAll('[data-task-runtime]').forEach(b=>b.onclick=()=>show(byId.get(b.dataset.taskRuntime)));show(nodes[0]);}

async function loadArtifacts(){try{const q=state.runId?`?run_id=${encodeURIComponent(state.runId)}`:'';state.artifacts=await fetchJSON(`/api/control/artifacts${q}`);renderDeliverables();}catch(e){toast(`文件读取失败：${e.message}`,true);}}

function providerDef(id){return (state.providers?.providers||[]).find(x=>x.id===id);}
async function saveProvider(){try{const payload={provider_id:$('providerSelect').value,api_key:$('providerKey').value||undefined,model:$('providerModel').value.trim(),base_url:$('providerBase').value.trim()};const data=await postJSON('/api/settings/provider',payload);state.providers=data.result;await loadBase();renderAll();toast('模型服务设置已保存');}catch(e){toast(`保存失败：${e.message}`,true);}}
async function testProvider(){const el=$('providerTestResult'),btn=$('testProviderBtn');buttonBusy(btn,true,'正在测试…');el.classList.remove('hidden','fail');el.textContent='正在执行真实 API 连接测试…';try{const payload={provider_id:$('providerSelect').value,api_key:$('providerKey').value||undefined,model:$('providerModel').value.trim(),base_url:$('providerBase').value.trim()};const data=await postJSON('/api/settings/test-provider',payload);const r=data.result||{};el.textContent=`连接成功 · ${r.model||'model'} · ${num(r.latency_ms,1)} ms · request ${short(r.request_id||'provider did not return id',40)}`;}catch(e){el.classList.add('fail');el.textContent=`连接失败：${e.message}`;}finally{buttonBusy(btn,false);}}

async function saveEndpoint(){try{const data=await postJSON('/api/settings/endpoint',endpointPayload());await loadBase();renderSettings();fillEndpoint(data.result?.endpoint||{});toast('远程执行节点已保存');}catch(e){toast(`保存节点失败：${e.message}`,true);}}
async function testEndpoint(endpointId){const id=endpointId||$('endpointId').value.trim();const el=$('endpointTestResult'),btn=endpointId?null:$('testEndpointBtn');buttonBusy(btn,true,'正在验证…');el.classList.remove('hidden','fail');el.textContent='正在发送真实 MQTT PLAN_REQUEST…';try{if(!id)throw new Error('请先填写并保存 Endpoint ID');const data=await postJSON('/api/settings/test-endpoint',{endpoint_id:id});const r=data.result||{};el.textContent=`VERIFIED · ${r.tier||'—'} · ${r.agent_id||'—'} · ${num(r.latency_ms,1)} ms · ${num(r.tool_call_count,0)} tool call(s)`;}catch(e){el.classList.add('fail');el.textContent=`远程节点验证失败：${e.message}`;}finally{buttonBusy(btn,false);}}
async function deleteEndpoint(endpointId){try{await postJSON('/api/settings/delete-endpoint',{endpoint_id:endpointId});await loadBase();renderSettings();toast('远程执行节点已删除');}catch(e){toast(`删除失败：${e.message}`,true);}}

function topologicalNodes(graph){const nodes=graph?.nodes||[],edges=graph?.edges||[];if(!nodes.length)return[];const indeg=new Map(nodes.map(n=>[n.id,0])),adj=new Map(nodes.map(n=>[n.id,[]]));for(const e of edges){if(indeg.has(e.target))indeg.set(e.target,(indeg.get(e.target)||0)+1);if(adj.has(e.source))adj.get(e.source).push(e.target);}const q=nodes.filter(n=>(indeg.get(n.id)||0)===0).sort((a,b)=>(b.priority||0)-(a.priority||0));const out=[];while(q.length){const n=q.shift();out.push(n);for(const t of adj.get(n.id)||[]){indeg.set(t,indeg.get(t)-1);if(indeg.get(t)===0)q.push(nodes.find(x=>x.id===t));}}return out.length===nodes.length?out:nodes;}
function renderObservatory(){const snap=state.snapshot;if(!snap){$('collaborationSvg').innerHTML='';$('collabEmpty').classList.remove('hidden');$('taskFlow').innerHTML='<div class="empty-state"><strong>等待真实运行数据</strong></div>';$('memoryFlow').innerHTML='';$('resourceFlow').innerHTML='';return;}const age=Math.max(0,Date.now()/1000-Number(snap.generated_at||0));$('observationStatus').innerHTML=`<span class="status-dot ${age<=5?'ok':'idle'}"></span>${age<=5?'快照新鲜':'历史快照'} · ${num(age,1)}s`;
  renderCollaboration();renderTaskFlow();renderMemoryFlow();renderResourceFlow();}
function capabilityMap(){return new Map((state.snapshot?.scheduler?.capabilities||[]).map(x=>[x.actor_id,x]));}
function renderCollaboration(){const topo=state.snapshot?.topology||{},nodes=topo.nodes||[],edges=topo.edges||[],caps=capabilityMap(),svg=$('collaborationSvg');$('topologyMeta').textContent=`Topology v${topo.version??'—'} · ${edges.length} active edges · connectivity ${num(topo.lambda2_or_connectivity,2)}`;if(!nodes.length){svg.innerHTML='';$('collabEmpty').classList.remove('hidden');$('collabDetail').innerHTML='<h4>运行说明</h4><p>当前快照没有真实 TopologySnapshot 节点。</p>';return;}$('collabEmpty').classList.add('hidden');const cx=450,cy=215,rx=Math.min(300,120+nodes.length*28),ry=Math.min(155,90+nodes.length*12);const pos=new Map();nodes.forEach((id,i)=>{const a=(Math.PI*2*i/nodes.length)-Math.PI/2;pos.set(id,{x:cx+rx*Math.cos(a),y:cy+ry*Math.sin(a)});});let html='<defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0,0 L7,3.5 L0,7 z" fill="#4a5060"></path></marker></defs>';for(const e of edges){const a=pos.get(e.source),b=pos.get(e.target);if(!a||!b)continue;html+=`<line class="collab-edge" data-edge="${esc(e.source)}|${esc(e.target)}" role="button" tabindex="0" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" marker-end="url(#arrow)"></line>`;}for(const id of nodes){const p=pos.get(id),cap=caps.get(id)||{};html+=`<g class="collab-node ${cap.online===true?'online':''}" data-node="${esc(id)}" role="button" tabindex="0"><circle cx="${p.x}" cy="${p.y}" r="36"></circle><text x="${p.x}" y="${p.y-2}">${esc(short(id.replace(/^agent[-_]/,''),18))}</text><text class="node-role" x="${p.x}" y="${p.y+14}">${esc(cap.online===false?'OFFLINE':cap.online===true?'ONLINE':'AGENT')}</text></g>`;}
  const now=Date.now();state.signalMessages=state.signalMessages.filter(x=>x.expires>now);for(const m of state.signalMessages){const a=pos.get(m.sender),b=pos.get(m.receiver);if(!a||!b)continue;html+=`<circle class="signal-dot" r="4"><animateMotion dur="1.15s" repeatCount="2" path="M ${a.x} ${a.y} L ${b.x} ${b.y}"></animateMotion></circle>`;}svg.innerHTML=html;const detail=$('collabDetail');detail.innerHTML=`<h4>真实过程语义</h4><div class="stage-detail-row"><span>拓扑边</span><strong>只来自 TopologySnapshot.active edges</strong></div><div class="stage-detail-row"><span>移动光点</span><strong>仅在本次轮询新观察到真实 SEND message_id 时短暂播放</strong></div><div class="stage-detail-row"><span>当前新增消息</span><strong>${state.signalMessages.length}</strong></div>`;const bindActivate=(el,fn)=>{el.addEventListener('click',fn);el.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();fn();}});};svg.querySelectorAll('[data-node]').forEach(g=>bindActivate(g,()=>{const id=g.dataset.node,cap=caps.get(id)||{};detail.innerHTML=`<h4>${esc(id)}</h4>${stageDetail('状态',cap.online===true?'ONLINE':cap.online===false?'OFFLINE':'UNKNOWN')}${stageDetail('调度可靠性',cap.reliability!=null?pct(cap.reliability):'—')}${stageDetail('延迟',cap.latency_ms!=null?num(cap.latency_ms,1)+' ms':'—')}${stageDetail('来源','scheduler.capabilities[]')}`;}));svg.querySelectorAll('[data-edge]').forEach(line=>bindActivate(line,()=>{const [s,t]=line.dataset.edge.split('|'),e=edges.find(x=>x.source===s&&x.target===t)||{};detail.innerHTML=`<h4>${esc(s)} → ${esc(t)}</h4>${stageDetail('Score',e.score!=null?num(e.score,3):'未提供')}${stageDetail('Reason',e.reason||'—')}${stageDetail('Task IDs',(e.task_ids||[]).join(', ')||'—')}${stageDetail('来源','TopologySnapshot.edges[]')}`;}));}
function stageDetail(name,value){return `<div class="stage-detail-row"><span>${esc(name)}</span><strong>${esc(value)}</strong></div>`;}

function renderLab(){const c=state.control||{};$('scenarioCards').innerHTML=(c.scenarios||[]).map(x=>`<div class="lab-card"><div class="lab-card-top"><h3>${esc(x.name)}</h3><span class="req-state implemented">REAL BACKEND</span></div><p>${esc(x.description)}</p><div class="lab-truth">运行后是否达标以 snapshot authenticity、scheduler provenance、Verifier 与 Evidence 为准。</div><button type="button" class="ghost-button" data-start-scenario="${esc(x.id)}">启动场景</button></div>`).join('');$('scenarioCards').querySelectorAll('[data-start-scenario]').forEach(b=>b.onclick=()=>controlAction('/api/control/start-scenario',{scenario:b.dataset.startScenario},'lab'));
  $('faultCards').innerHTML=(c.experiments?.faults||[]).map(x=>`<div class="lab-card"><div class="lab-card-top"><h3>${esc(x.name)}</h3><span class="req-state implemented">${esc(x.id)}</span></div><p>${esc(x.meaning)}</p><div class="lab-truth">有活动 Run 时写入 LiveFaultMailbox；无活动 Run 时启动独立故障实验。前端不直接改任务状态。</div><button type="button" class="ghost-button" data-start-fault="${esc(x.id)}">注入并验证</button></div>`).join('');$('faultCards').querySelectorAll('[data-start-fault]').forEach(b=>b.onclick=()=>controlAction('/api/control/start-fault',{fault:b.dataset.startFault,requirement:$('requirementInput').value},'lab'));
  $('benchmarkCards').innerHTML=(c.experiments?.benchmarks||[]).map(x=>`<div class="lab-card"><div class="lab-card-top"><h3>${esc(x.name)}</h3><span class="req-state implemented">MEASUREMENT</span></div><p>${esc(x.truth)}</p><button type="button" class="ghost-button" data-start-bench="${esc(x.id)}">开始实验</button></div>`).join('');$('benchmarkCards').querySelectorAll('[data-start-bench]').forEach(b=>b.onclick=()=>controlAction('/api/control/start-benchmark',{benchmark:b.dataset.startBench},'lab'));
  const inj=c.injections||[];$('injectionList').innerHTML=inj.length?inj.slice(0,20).map(x=>`<div class="compact-row"><span>${esc(short(x.request_id,26))}</span><span>${esc(short(x.run_id,26))}</span><span>${statePill(x.state)}</span><span>${ts(x.finished_at||x.requested_at)}</span></div>`).join(''):'<div class="subtle">暂无故障请求。</div>';}

function requirementCard(title,stateName,desc){return `<div class="requirement-card"><div class="requirement-top"><h3>${esc(title)}</h3><span class="req-state ${esc(stateName.cls)}">${esc(stateName.label)}</span></div><p>${esc(desc)}</p></div>`;}

function renderLineage(){const snap=state.snapshot||{},ctl=state.control?.traceability||{},line=[...(snap.data_lineage||[]),...(ctl.fields||[])];$('lineageSummary').innerHTML=[metricCell('Lineage fields',num(line.length,0),'snapshot + control'),metricCell('State contracts',num((snap.state_machine?.display_status_contracts||[]).length+(snap.state_machine?.transition_contracts||[]).length+(ctl.states||[]).length,0),'explicit entry rules'),metricCell('Control actions',num((ctl.actions||[]).length,0),'real backend endpoints'),metricCell('Animation contract','EVENT-DRIVEN','no decorative runtime state')].join('');$('lineageTable').innerHTML=line.length?line.map(x=>`<tr><td>${esc(x.ui)}</td><td><code>${esc(x.api||'/api/snapshot')}</code></td><td><code>${esc(x.field||'—')}</code></td><td>${esc(x.source||'—')}</td><td>${esc(x.calculation||'—')}</td></tr>`).join(''):'<tr><td colspan="5">当前没有数据血缘定义</td></tr>';const task=(snap.state_machine?.transition_contracts||[]).map(x=>({family:'Task',state:x.state,timing:x.event,entered_when:x.entered_when,source:x.source}));const display=snap.state_machine?.display_status_contracts||[];const controls=ctl.states||[];const contracts=[...task,...display,...controls];$('stateContract').innerHTML=contracts.length?contracts.map(x=>`<tr><td>${esc(x.family||'Task')}</td><td>${esc(x.state||'—')}</td><td>${esc(x.timing||x.event||'process lifecycle')}</td><td>${esc(x.entered_when||'—')}</td><td>${esc(x.source||'—')}</td></tr>`).join(''):'<tr><td colspan="5">当前没有状态契约</td></tr>';const actions=(ctl.actions||[]).map(x=>({name:x.ui,meaning:`${x.endpoint}；${x.effect}`}));actions.push({name:'协同图移动光点',meaning:'仅在 SSE/刷新观察到新的真实 SEND message_id 时播放约 2 秒；历史消息不循环冒充实时通信。'},{name:'Task 节点高亮',meaning:'仅在相邻两次 authoritative snapshot 中观察到任务状态变化时短暂高亮。'},{name:'Memory 流动动画',meaning:'仅在 context_pack_count 相比上一次 snapshot 增加时短暂播放。'},{name:'等待 pulse',meaning:'仅表示前端尚未取得 snapshot；不表示 Agent、模型或网络正在运行。'});$('interactionAudit').innerHTML=actions.map(x=>`<div class="audit-row"><strong>${esc(x.name)}</strong><span>${esc(x.meaning)}</span></div>`).join('');}


// v1.7 truth-preserving UI overrides -------------------------------------------------
function actualTier(a){return String(a?.actual_execution_tier||a?.execution_tier||'edge').toLowerCase();}
function measuredLatencyLabel(a){const m=a?.metadata||{};const count=Number(m.latency_measurement_count||0);return count>0&&Number.isFinite(Number(a?.latency_ms))?`${num(a.latency_ms,1)} ms · measured (${count})`:'未测量';}

function renderAgents(){
  const caps=state.snapshot?.scheduler?.capabilities||[],assign=state.snapshot?.scheduler?.assignments||[],auth=state.snapshot?.authenticity||{};
  const agents=caps.filter(x=>String(x.kind||'').toLowerCase()==='agent'),online=agents.filter(x=>x.online===true).length;
  const apiBound=agents.filter(x=>x.metadata?.adapter_bound===true&&Boolean(x.metadata?.api_transport)&&!['mock','unbound','test_fixture'].includes(String(x.metadata?.authenticity_mode||''))).length;
  const strict=agents.filter(x=>x.metadata?.authenticity_mode==='real_api'&&x.metadata?.official_endpoint_verified===true).length;
  const tiers={device:[],edge:[],cloud:[]};for(const a of assign){const t=actualTier(a);(tiers[t]||tiers.edge).push(a);}
  $('agentSummary').innerHTML=[metricCell('Runtime Agents',num(agents.length,0),'Capability Registry only'),metricCell('API-bound',num(apiBound,0),'adapter_bound + API mode'),metricCell('Strict official',num(strict,0),'official endpoint verified'),metricCell('Assignments',num(assign.length,0),'committed by Scheduler'),metricCell('Verdict',auth.verdict||'—','snapshot authenticity')].join('');
  const truth=$('agentTruthSummary');if(truth){const details=auth.assigned_agents||[];const bad=details.filter(x=>!x.adapter_bound||['mock','unbound','test_fixture'].includes(x.mode));truth.innerHTML=`<div class="truth-strip-icon ${bad.length?'bad':'ok'}">${bad.length?'!':'✓'}</div><div><strong>${bad.length?'检测到非真实 Runtime Agent':'Runtime Agent 绑定检查通过'}</strong><span>${details.length?`${details.length} 个已分配 Agent；每个都由 snapshot authenticity.agent_details 给出 Adapter / transport / endpoint 证据。`:'当前 Run 尚无已分配 Agent；Agent Studio 模板不会被计为 Runtime Agent。'}</span></div><button type="button" class="ghost-button" data-go="judge">查看真实性证据</button>`;}
  $('agentCards').innerHTML=agents.length?agents.map(a=>{const meta=a.metadata||{},measured=meta.posterior_success_rate??meta.empirical_success_rate,mode=meta.authenticity_mode||'unclassified';return `<div class="agent-card"><div class="agent-card-top"><div class="agent-title"><div class="agent-avatar">${esc((a.actor_id||'A').slice(-1).toUpperCase())}</div><div><strong>${esc(short(a.actor_id,32))}</strong><span>${esc(meta.tier||a.device_location||'tier unknown')} · ${a.online===true?'ONLINE':a.online===false?'OFFLINE':'UNKNOWN'}</span></div></div><span class="auth-badge ${authModeClass(mode)}">${esc(authModeLabel(mode))}</span></div><div class="agent-auth-grid"><span><b>Adapter</b>${meta.adapter_bound?'BOUND':'UNBOUND'}</span><span><b>Transport</b>${esc(meta.api_transport||'—')}</span><span><b>Official</b>${meta.official_endpoint_verified?'VERIFIED':'NO'}</span><span><b>Model/API</b>${esc(meta.endpoint_host||'—')}</span></div><div class="agent-meta"><span class="mini-chip" title="来源 scheduler.capabilities[].reliability；无运行样本时为配置先验，有样本后为后验摘要">调度可靠性 ${Number.isFinite(Number(a.reliability))?pct(a.reliability):'—'}</span><span class="mini-chip">延迟 ${esc(measuredLatencyLabel(a))}</span>${measured!=null?`<span class="mini-chip">实测成功率 ${pct(measured)}</span>`:''}</div></div>`}).join(''):'<div class="empty-state"><strong>当前 Run 没有 Runtime Agent capability 数据</strong><span>配置模板不会在这里冒充运行中的 Agent。</span></div>';
  $('tierLanes').innerHTML=['device','edge','cloud'].map(t=>`<div class="tier-lane"><div class="tier-label"><strong>${t.toUpperCase()}</strong><span>${tiers[t].length} actual assignments</span></div>${tiers[t].map(a=>`<div class="assignment-pill"><span class="agent-dot"></span><div><strong>${esc(short(a.task_id,24))}</strong><span> → ${esc(short(a.agent_id,25))}</span><small>实际 ${esc(actualTier(a).toUpperCase())} · 推荐 ${esc(String(a.recommended_tier||'—').toUpperCase())}${a.placement_fallback?' · FALLBACK':''}</small></div></div>`).join('')||'<div class="subtle">当前 Run 未实际分配到该层级</div>'}</div>`).join('');
  renderAgentConfigList();
}
function clearAgentForm(){$('agentId').value='';$('agentName').value='';$('agentRole').value='';$('agentTier').value='cloud';$('agentEnabled').value='true';$('agentSkills').value='';$('agentPermissions').value='*';$('agentModel').value='';$('agentMaxLoad').value='1';}
function fillAgent(row){$('agentId').value=row.agent_id||'';$('agentName').value=row.name||'';$('agentRole').value=row.role||'';$('agentTier').value=row.tier||'cloud';$('agentEnabled').value=String(row.enabled!==false);$('agentSkills').value=(row.skills||[]).join(',');$('agentPermissions').value=(row.permissions||['*']).join(',');$('agentModel').value=row.model||'';$('agentMaxLoad').value=row.max_load||1;}
function agentPayload(){return {agent_id:$('agentId').value.trim(),name:$('agentName').value.trim(),role:$('agentRole').value.trim(),tier:$('agentTier').value,skills:$('agentSkills').value,permissions:$('agentPermissions').value,model:$('agentModel').value.trim(),max_load:Number($('agentMaxLoad').value||1),enabled:$('agentEnabled').value==='true'};}
function renderAgentConfigList(){const el=$('agentConfigList');if(!el)return;const rows=state.agents?.agents||[];el.innerHTML=rows.length?rows.map(x=>`<div class="endpoint-item"><div class="endpoint-item-main"><span class="endpoint-tier">${esc(String(x.tier||'cloud').toUpperCase())}</span><div><strong>${esc(x.name||x.agent_id)}</strong><span>${esc(x.agent_id)} · ${x.enabled===false?'DISABLED':'ENABLED'} · ${esc((x.skills||[]).join(', '))} · ${esc(x.model||'Provider 默认模型')}</span></div></div><div class="endpoint-actions"><button type="button" class="text-button" data-edit-agent="${esc(x.agent_id)}">编辑</button><button type="button" class="text-button danger-text" data-delete-agent="${esc(x.agent_id)}">删除</button></div></div>`).join(''):'<div class="empty-state"><strong>尚未配置 Agent 模板</strong><span>下一次 Run 会按真实所需 Skill 注册 Provider API Agent；未执行的模板不会显示成 Runtime Agent。</span></div>';el.querySelectorAll('[data-edit-agent]').forEach(b=>b.onclick=()=>{const r=rows.find(x=>x.agent_id===b.dataset.editAgent);if(r)fillAgent(r);});el.querySelectorAll('[data-delete-agent]').forEach(b=>b.onclick=async()=>{try{await postJSON('/api/settings/delete-agent',{agent_id:b.dataset.deleteAgent});await loadBase();renderAgents();toast('Agent 模板已删除；只影响后续新 Run');}catch(e){toast(`删除失败：${e.message}`,true);}});}
async function saveAgent(){try{await postJSON('/api/settings/agent',agentPayload());await loadBase();renderAgents();toast('Agent 模板已保存；下一次新 Run 生效');}catch(e){toast(`保存 Agent 失败：${e.message}`,true);}}

function renderDeliverables(){const f=state.artifacts||[];$('artifactSummary').innerHTML=[metricCell('Artifacts',num(f.length,0),'approved server roots'),metricCell('Results',num(f.filter(x=>x.category==='results').length,0),'run result files'),metricCell('Evidence',num(f.filter(x=>x.category==='evidence').length,0),'content-addressed evidence'),metricCell('Deliverables',num(f.filter(x=>x.category==='deliverables').length,0),'task outputs')].join('');$('artifactList').innerHTML=f.length?f.map(x=>`<div class="file-row"><div class="file-main"><div class="file-icon">${x.category==='evidence'?'◇':'▱'}</div><div><strong>${esc(x.title||x.display_name||x.name)}</strong><span>${esc(x.display_name||x.name)} · ${esc(x.context||x.category)}</span></div></div><div class="file-cell">${num(Number(x.bytes||0)/1024,1)} KB</div><div class="file-cell">${ts(x.modified_at)}</div><div class="file-actions">${x.previewable?`<button type="button" class="text-button" data-preview-artifact="${esc(x.artifact_id)}">预览</button>`:''}<a class="text-button artifact-download" href="/api/control/artifact-download?artifact_id=${encodeURIComponent(x.artifact_id)}">下载</a></div></div>`).join(''):'<div class="empty-state"><strong>尚无交付物</strong><span>完成真实任务后，结果、任务交付物和证据会出现在这里。</span></div>';$('artifactList').querySelectorAll('[data-preview-artifact]').forEach(b=>b.onclick=()=>previewArtifact(b.dataset.previewArtifact));}
async function previewArtifact(id){try{const data=await fetchJSON(`/api/control/artifact-preview?artifact_id=${encodeURIComponent(id)}`);$('artifactModalTitle').textContent=data.title||data.name||'交付物预览';$('artifactModalMeta').textContent=`${data.display_name||data.name||''} · ${data.context||data.category||''} · ${num((data.bytes||0)/1024,1)} KB`;$('artifactPreview').textContent=data.content||'（无可预览文本）';$('artifactModal').classList.remove('hidden');}catch(e){toast(`预览失败：${e.message}`,true);}}

function renderSettings(){const p=state.providers;if(!p)return;const active=p.active||{},select=$('providerSelect');select.innerHTML=(p.providers||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');select.value=active.provider_id||'deepseek';const cfg=p.provider_configs?.[select.value]||active;$('providerModel').value=cfg.model||'';$('providerBase').value=cfg.base_url||'';$('providerKey').value='';const def=providerDef(select.value);$('providerKey').disabled=def?.requires_key===false;$('keyStatusText').textContent=def?.requires_key===false?'本地 Provider 不使用云 Key':cfg.api_key_present?'当前 Provider 已配置':'当前 Provider 未配置';$('providerSecurity').textContent=`当前 Provider 独立密钥存储：${active.secret_storage||'后端受控存储'}；切换 Provider 不复用其他服务的 Key。`;renderEndpointList();renderReadiness($('settingsReadiness'));}
function onProviderChanged(){const id=$('providerSelect').value,d=providerDef(id),cfg=state.providers?.provider_configs?.[id]||{};$('providerBase').value=cfg.base_url??d?.default_base_url??'';$('providerModel').value=cfg.model??d?.default_model??'';$('providerKey').value='';$('providerKey').disabled=d?.requires_key===false;$('keyStatusText').textContent=d?.requires_key===false?'本地 Provider 不使用云 Key':cfg.api_key_present?'当前 Provider 已配置':'当前 Provider 未配置';}
