function fillEndpoint(row){$('endpointId').value=row.endpoint_id||'';$('endpointName').value=row.name||'';$('endpointTier').value=row.tier||'edge';$('endpointAgentId').value=row.agent_id||'';$('endpointHost').value=row.host||'';$('endpointPort').value=row.port||1883;$('endpointPrefix').value=row.topic_prefix||'mosaic/v3';$('endpointUsername').value=row.username||'';$('endpointPassword').value='';$('endpointTls').value=String(Boolean(row.tls));$('endpointEnabled').value=String(row.enabled!==false);}
