function renderEndpointList(){const rows=state.endpoints?.endpoints||[],el=$('endpointList');if(!el)return;el.innerHTML=rows.length?rows.map(x=>`<div class="endpoint-item"><div class="endpoint-item-main"><span class="endpoint-tier">${esc(String(x.tier||'edge').toUpperCase())}</span><div><strong>${esc(x.name||x.endpoint_id)}</strong><span>${esc(x.agent_id)} · MQTT ${x.tls?'TLS':'no TLS'} · ${x.username?'authenticated user':'no username'} · 地址仅设置页可见</span></div></div><div class="endpoint-actions"><button type="button" class="text-button" data-edit-endpoint="${esc(x.endpoint_id)}">编辑</button><button type="button" class="text-button" data-probe-endpoint="${esc(x.endpoint_id)}">连通验证</button><button type="button" class="text-button" data-accept-endpoint="${esc(x.endpoint_id)}">联合验收</button><button type="button" class="text-button danger-text" data-delete-endpoint="${esc(x.endpoint_id)}">删除</button></div></div>`).join(''):'<div class="empty-state"><strong>尚未注册远程执行节点</strong><span>单机运行无需配置；跨主机部署建议 TLS + 认证。</span></div>';el.querySelectorAll('[data-edit-endpoint]').forEach(b=>b.onclick=()=>{const row=rows.find(x=>x.endpoint_id===b.dataset.editEndpoint);if(row)fillEndpoint(row);});el.querySelectorAll('[data-probe-endpoint]').forEach(b=>b.onclick=()=>testEndpoint(b.dataset.probeEndpoint));el.querySelectorAll('[data-accept-endpoint]').forEach(b=>b.onclick=()=>controlAction('/api/control/start-remote-acceptance',{endpoint_id:b.dataset.acceptEndpoint},'tasks'));el.querySelectorAll('[data-delete-endpoint]').forEach(b=>b.onclick=()=>deleteEndpoint(b.dataset.deleteEndpoint));}

function renderTaskFlow(){
  const graph=state.snapshot?.task_graph||{},nodes=graph.nodes||[],edges=graph.edges||[];$('taskCountMeta').textContent=`${nodes.length} tasks · ${edges.length} authoritative edges`;
  if(!nodes.length){$('taskFlow').innerHTML='<div class="empty-state"><strong>没有 TaskGraph 数据</strong></div>';return;}
  const ids=new Set(nodes.map(n=>String(n.id))),validEdges=edges.filter(e=>ids.has(String(e.source))&&ids.has(String(e.target)));
  const preds=new Map(nodes.map(n=>[String(n.id),[]]));for(const e of validEdges)preds.get(String(e.target)).push(String(e.source));
  const depth=new Map();function d(id,seen=new Set()){if(depth.has(id))return depth.get(id);if(seen.has(id))return 0;seen.add(id);const ps=preds.get(id)||[];const v=ps.length?1+Math.max(...ps.map(p=>d(p,new Set(seen)))):0;depth.set(id,v);return v;}nodes.forEach(n=>d(String(n.id)));
  const layers={};for(const n of nodes){const k=depth.get(String(n.id))||0;(layers[k]||(layers[k]=[])).push(n);}Object.values(layers).forEach(a=>a.sort((x,y)=>String(x.id).localeCompare(String(y.id))));
  const maxDepth=Math.max(...[...depth.values(),0]),nodeW=178,nodeH=86,gapX=78,gapY=24,pad=26;let maxRows=1;Object.values(layers).forEach(a=>maxRows=Math.max(maxRows,a.length));const width=Math.max(640,pad*2+(maxDepth+1)*nodeW+maxDepth*gapX),height=Math.max(180,pad*2+maxRows*nodeH+(maxRows-1)*gapY);const pos={};for(const [k,arr] of Object.entries(layers)){const layer=Number(k),total=arr.length*nodeH+(arr.length-1)*gapY,start=(height-total)/2;arr.forEach((n,i)=>pos[String(n.id)]={x:pad+layer*(nodeW+gapX),y:start+i*(nodeH+gapY)});}
  const paths=validEdges.map(e=>{const a=pos[String(e.source)],b=pos[String(e.target)],x1=a.x+nodeW,y1=a.y+nodeH/2,x2=b.x,y2=b.y+nodeH/2,m=(x1+x2)/2;return `<path class="dag-edge" d="M ${x1} ${y1} C ${m} ${y1}, ${m} ${y2}, ${x2} ${y2}" marker-end="url(#dagArrow)"/>`;}).join('');
  const boxes=nodes.map(n=>{const p=pos[String(n.id)],cls=n.status==='SUCCEEDED'?'success':n.status==='FAILED'?'failed':n.status==='RUNNING'?'running':n.status==='VERIFYING'?'verifying':'',changed=state.changedTasks.has(n.id)?'transitioned':'';return `<g class="dag-node ${cls} ${changed}" transform="translate(${p.x},${p.y})"><rect width="${nodeW}" height="${nodeH}" rx="14"></rect><text x="12" y="23" class="dag-title">${esc(short(n.label,25))}</text><text x="12" y="48" class="dag-state">${esc(n.status||'UNKNOWN')}</text><text x="12" y="68" class="dag-agent">${esc(short(n.assignment?.agent_id||'未分配',24))}</text></g>`;}).join('');
  $('taskFlow').innerHTML=`<svg class="dag-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Task DAG：箭头只来自 task_graph.edges"><defs><marker id="dagArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"></path></marker></defs>${paths}${boxes}</svg>`;
}
