function setDeepPanel(name){
  const allowed=['panorama','dag','scheduler','collaboration','communication','memory','verifier','recovery','lab','lineage'];
  state.deep=allowed.includes(name)?name:'panorama';
  document.querySelectorAll('.deep-tab').forEach(b=>b.classList.toggle('active',b.dataset.deep===state.deep));
  document.querySelectorAll('[data-deep-panel]').forEach(p=>p.classList.toggle('active',p.dataset.deepPanel===state.deep));
  renderJudgeDeep();
}
