function renderJudgeDag(){const target=$('deepDagGraph'),meta=$('deepDagMeta'),ins=$('deepDagInspector');if(!target||!meta||!ins)return;const graph=state.snapshot?.task_graph||{},nodes=graph.nodes||[],edges=graph.edges||[];meta.textContent=`${nodes.length} tasks · ${edges.length} authoritative edges`;if(!nodes.length){target.innerHTML=deepEmpty('等待 TaskGraph','提交并运行任务后，这里只显示 authoritative task_graph.edges。');ins.innerHTML=deepEmpty('Task Inspector','点击 DAG 节点查看需求来源、Agent、Model、Tool、Verifier 与 Evidence。');return;}
  const ids=new Set(nodes.map(n=>String(n.id))),valid=edges.filter(e=>ids.has(String(e.source))&&ids.has(String(e.target))),preds=new Map(nodes.map(n=>[String(n.id),[]]));valid.forEach(e=>preds.get(String(e.target)).push(String(e.source)));const depth=new Map();function dep(id,seen=new Set()){if(depth.has(id))return depth.get(id);if(seen.has(id))return 0;seen.add(id);const ps=preds.get(id)||[],v=ps.length?1+Math.max(...ps.map(p=>dep(p,new Set(seen)))):0;depth.set(id,v);return v;}nodes.forEach(n=>dep(String(n.id)));const layers={};nodes.forEach(n=>{const k=depth.get(String(n.id))||0;(layers[k]||(layers[k]=[])).push(n)});Object.values(layers).forEach(a=>a.sort((x,y)=>String(x.id).localeCompare(String(y.id))));const maxDepth=Math.max(...[...depth.values(),0]),nodeW=176,nodeH=90,gapX=72,gapY=22,pad=24;let maxRows=1;Object.values(layers).forEach(a=>maxRows=Math.max(maxRows,a.length));const width=Math.max(660,pad*2+(maxDepth+1)*nodeW+maxDepth*gapX),height=Math.max(240,pad*2+maxRows*nodeH+(maxRows-1)*gapY),pos={};for(const [k,arr] of Object.entries(layers)){const layer=Number(k),total=arr.length*nodeH+(arr.length-1)*gapY,start=(height-total)/2;arr.forEach((n,i)=>pos[String(n.id)]={x:pad+layer*(nodeW+gapX),y:start+i*(nodeH+gapY)})}const paths=valid.map(e=>{const a=pos[String(e.source)],b=pos[String(e.target)],x1=a.x+nodeW,y1=a.y+nodeH/2,x2=b.x,y2=b.y+nodeH/2,m=(x1+x2)/2;return `<path class="dag-edge" d="M ${x1} ${y1} C ${m} ${y1}, ${m} ${y2}, ${x2} ${y2}" marker-end="url(#deepDagArrow)"/>`}).join('');const boxes=nodes.map(n=>{const p=pos[String(n.id)],cls=n.status==='SUCCEEDED'?'success':n.status==='FAILED'?'failed':n.status==='RUNNING'?'running':n.status==='VERIFYING'?'verifying':'';return `<g class="dag-node ${cls}" data-deep-task="${esc(n.id)}" role="button" tabindex="0" transform="translate(${p.x},${p.y})"><rect width="${nodeW}" height="${nodeH}" rx="12"></rect><text x="12" y="24" class="dag-title">${esc(short(n.label||n.id,25))}</text><text x="12" y="49" class="dag-state">${esc(n.status||'UNKNOWN')}</text><text x="12" y="71" class="dag-agent">${esc(short(n.assignment?.agent_id||'未分配',24))}</text></g>`}).join('');target.innerHTML=`<svg class="dag-svg" viewBox="0 0 ${width} ${height}"><defs><marker id="deepDagArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10z"></path></marker></defs>${paths}${boxes}</svg>`;const show=n=>{const events=deepEventsFor(n.id),tool=events.find(e=>eventType(e)==='TOOL_EXECUTED')?.payload?.tool_call||{},verify=events.filter(e=>eventType(e)==='TASK_VERIFIED').at(-1),evidence=(verify?.payload?.evidence_ids||[]);ins.innerHTML=`<h4 class="inspector-title">${esc(n.label||n.id)}</h4><p class="inspector-sub">${esc(n.id)} · ${esc(n.status||'UNKNOWN')}</p><div class="inspector-block"><span>Dependencies</span><strong>${esc((preds.get(String(n.id))||[]).join(' → ')||'ROOT')}</strong></div><div class="inspector-block"><span>Scheduler Assignment</span><strong>${esc(n.assignment?.agent_id||'未分配')} · ${esc(actualTier(n.assignment||{}).toUpperCase())}</strong></div><div class="inspector-block"><span>Model</span><code>${esc(n.assignment?.model_id||'system / unavailable')}</code></div><div class="inspector-block"><span>Tool Call</span><code>${esc(tool.tool_name||'当前无 TOOL_EXECUTED')}</code></div><div class="inspector-block"><span>Verification</span><strong>${esc(verify?.payload?.passed===true?'PASS':verify?.payload?.passed===false?'FAIL':'等待验证')}</strong></div><div class="inspector-block"><span>Evidence IDs</span><code>${esc(evidence.join(', ')||'尚无')}</code></div>`};target.querySelectorAll('[data-deep-task]').forEach(g=>{g.onclick=()=>show(nodes.find(n=>String(n.id)===g.dataset.deepTask));g.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')g.click()}});show(nodes[0]);}
function renderJudgeScheduler(){const el=$('deepScheduler'),meta=$('deepSchedulerMeta');if(!el||!meta)return;const sch=state.snapshot?.scheduler||{},a=sch.assignments||[],caps=sch.capabilities||[],release=state.control?.release_benchmarks?.scheduler_ablation?.data||null;meta.textContent=`${a.length} assignments · ${sch.solver_integrity?.verdict||'solver provenance unavailable'}`;if(!a.length){el.innerHTML=deepEmpty('等待真实 Assignment','只有 Scheduler 已提交的 Assignment 才会显示；不会生成虚假的候选或优化结果。');return;}const costs=a.map(x=>Number(x.total_cost??x.cost??0)).filter(Number.isFinite),avg=costs.length?costs.reduce((x,y)=>x+y,0)/costs.length:null;const rel=caps.filter(x=>String(x.kind||'').toLowerCase()==='agent').slice(0,12);const costRows=a.slice(0,20).map(x=>{const c=x.cost_breakdown||{};return [esc(short(x.task_id,24)),esc(`${num(c.fixed||0,3)} + ${num(c.latency||0,3)}`),esc(`${num(c.token||0,3)} + ${num(c.energy||0,3)}`),esc(`${num(c.failure||0,3)} + ${num(c.load||0,3)} + ${num(c.migration||0,3)} + ${num(c.placement||0,3)}`),esc(num(x.total_cost??x.cost??0,4))]});const ort=release?.modes?.ortools||{};const releaseCard=release?`<div class="deep-card"><h4>v1.9.0 受控 Scheduler Benchmark</h4><p>与当前 Run 分开：同 tasks / registry / cost weights / capacities。${ort.available?`OR-Tools objective = ${num(ort.scheduler_objective_total_cost,4)}`:'当前构建环境 OR-Tools unavailable；没有把其他求解器冒充 OR-Tools。'}</p></div>`:'';el.innerHTML=`<div class="deep-card math-card"><h4>优化目标与约束</h4><div class="math-block">min Σ<sub>t,d</sub> x<sub>td</sub>C<sub>td</sub></div><p>C = C<sub>fixed</sub> + C<sub>latency</sub> + C<sub>token</sub> + C<sub>energy</sub> + C<sub>failure</sub> + C<sub>migration</sub> + C<sub>load</sub> + C<sub>placement</sub></p><div class="formula-notes"><span>每个 Task 仅分配一次</span><span>设备容量约束</span><span>技能/权限可行性</span><span>隐私与位置约束</span></div></div><div class="deep-card"><h4>真实 Assignment</h4><div class="deep-metrics">${deepMetric('Assignments',num(a.length,0))}${deepMetric('Solver',sch.solver_integrity?.verdict||'—')}${deepMetric('Average cost',avg==null?'—':num(avg,4))}${deepMetric('Actual tiers',[...new Set(a.map(actualTier))].join(' / ')||'—')}</div>${deepTable(['Task','Selected Agent','Actual Tier','Recommended','Total Cost'],a.slice(0,30).map(x=>[esc(short(x.task_id,28)),esc(short(x.agent_id,26)),`<span class="reason-chip">${esc(actualTier(x).toUpperCase())}</span>`,esc(String(x.recommended_tier||'—').toUpperCase()),esc(Number.isFinite(Number(x.total_cost??x.cost))?num(x.total_cost??x.cost,4):'—')]))}</div><div class="deep-card"><h4>Cost Breakdown · 实际被选 Assignment</h4>${deepTable(['Task','fixed + latency','token + energy','failure + load + migration + placement','Total'],costRows)}</div><div class="deep-card math-card"><h4>Agent Reliability · Beta Posterior</h4><div class="math-block">E[p] = α / (α + β) &nbsp;&nbsp; · &nbsp;&nbsp; γ = e<sup>−λΔt</sup></div><p>可靠性不是固定“成功率”文案；若后端存在 posterior/measurement metadata，则以能力记录为准。当前 capability 数：${num(rel.length,0)}。</p></div>${releaseCard}`;}
function renderJudgeCollaboration(){const svg=$('deepCollaborationSvg'),meta=$('deepCollabMeta'),ins=$('deepCollabInspector');if(!svg||!meta||!ins)return;const top=state.snapshot?.topology||{},nodes=top.nodes||[],edges=top.edges||[],comm=state.snapshot?.communication?.items||[];meta.textContent=`Topology v${top.version??'—'} · ${edges.length} directed edges · Algebraic Connectivity λ₂=${num(top.lambda2??top.lambda2_or_connectivity,3)}`;if(!nodes.length){svg.innerHTML='';ins.innerHTML=deepEmpty('等待真实拓扑','TopologySnapshot 尚无节点。');return;}const cx=450,cy=215,rx=Math.min(310,135+nodes.length*25),ry=Math.min(155,100+nodes.length*10),pos=new Map();nodes.forEach((id,i)=>{const a=2*Math.PI*i/nodes.length-Math.PI/2;pos.set(id,{x:cx+rx*Math.cos(a),y:cy+ry*Math.sin(a)})});let html='<defs><marker id="deepArrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0,0 L7,3.5 L0,7 z" fill="#98a2b3"></path></marker></defs>';edges.forEach(e=>{const a=pos.get(e.source),b=pos.get(e.target);if(a&&b){const msgs=comm.filter(m=>(m.source===e.source&&m.target===e.target)||(m.sender===e.source&&m.receiver===e.target)).length,w=Math.min(5,1.4+msgs*.45),reciprocal=edges.some(r=>r.source===e.target&&r.target===e.source),dx=b.x-a.x,dy=b.y-a.y,len=Math.max(1,Math.hypot(dx,dy)),sign=String(e.source)<String(e.target)?1:-1,off=reciprocal?24*sign:0,mx=(a.x+b.x)/2+(-dy/len)*off,my=(a.y+b.y)/2+(dx/len)*off;html+=`<path data-deep-edge="${esc(e.source)}|${esc(e.target)}" d="M ${a.x} ${a.y} Q ${mx} ${my} ${b.x} ${b.y}" fill="none" stroke="#98a2b3" stroke-width="${w}" marker-end="url(#deepArrow)" style="cursor:pointer"></path>`}});nodes.forEach(id=>{const p=pos.get(id);html+=`<g data-deep-agent="${esc(id)}" style="cursor:pointer"><circle cx="${p.x}" cy="${p.y}" r="36" fill="#f8fbff" stroke="#bfd0ee" stroke-width="1.5"></circle><text x="${p.x}" y="${p.y}" text-anchor="middle" font-size="11" font-weight="700" fill="#1d2939">${esc(short(id.replace(/^agent[-_]/,''),16))}</text><text x="${p.x}" y="${p.y+15}" text-anchor="middle" font-size="9" fill="#667085">AGENT</text></g>`});svg.innerHTML=html;const showAgent=id=>{const related=comm.filter(m=>[m.source,m.target,m.sender,m.receiver].includes(id)),neighbors=[...new Set(edges.filter(e=>e.source===id||e.target===id).map(e=>e.source===id?e.target:e.source))];ins.innerHTML=`<h4 class="inspector-title">${esc(id)}</h4><p class="inspector-sub">真实 TopologySnapshot 节点</p><div class="inspector-block"><span>Communication decisions</span><strong>${num(related.length,0)}</strong></div><div class="inspector-block"><span>Unique neighbors</span><strong>${esc(neighbors.join(', ')||'无')}</strong></div>`};const showEdge=(a,b)=>{const related=comm.filter(m=>(m.source===a&&m.target===b)||(m.sender===a&&m.receiver===b));const counts={};related.forEach(m=>counts[m.policy_action||m.action||'UNKNOWN']=(counts[m.policy_action||m.action||'UNKNOWN']||0)+1);const edge=edges.find(e=>e.source===a&&e.target===b)||{};ins.innerHTML=`<h4 class="inspector-title">${esc(a)} → ${esc(b)}</h4><p class="inspector-sub">Edge score: Sᵢⱼ = 0.40D + 0.30I + 0.20R + 0.10L</p><div class="inspector-block"><span>Edge Score</span><strong>${Number.isFinite(Number(edge.score))?num(edge.score,4):'—'}</strong></div><div class="inspector-block"><span>Reason</span><strong>${esc(edge.reason||'—')}</strong></div><div class="inspector-block"><span>Task IDs</span><code>${esc((edge.task_ids||[]).join(', ')||'—')}</code></div><div class="inspector-block"><span>Messages / Decisions</span><strong>${num(related.length,0)}</strong></div><div class="inspector-block"><span>Policy Actions</span><code>${esc(Object.entries(counts).map(([k,v])=>`${k}:${v}`).join(' · ')||'无记录')}</code></div>`};svg.querySelectorAll('[data-deep-agent]').forEach(g=>g.onclick=()=>showAgent(g.dataset.deepAgent));svg.querySelectorAll('[data-deep-edge]').forEach(g=>g.onclick=()=>{const [a,b]=g.dataset.deepEdge.split('|');showEdge(a,b)});if(edges.length)showEdge(edges[0].source,edges[0].target);else showAgent(nodes[0]);}
function renderJudgeCommunication(){const el=$('deepCommunication'),meta=$('deepCommMeta');if(!el||!meta)return;const c=state.snapshot?.communication||{},items=c.items||[],counts=c.action_counts||{},release=state.control?.release_benchmarks?.topology_replay||null,bench=release?.data||null;meta.textContent=`${num(c.total??items.length,0)} policy decisions`;const total=Math.max(1,Object.values(counts).reduce((a,b)=>a+Number(b||0),0)||items.length);const bars=['SEND','MERGE','DEFER','DROP'].map(k=>`<div class="deep-bar-row"><span>${k}</span><div class="deep-bar-track"><div class="deep-bar-fill ${k==='DROP'?'muted':k==='DEFER'?'warn':''}" style="width:${Math.min(100,100*Number(counts[k]||0)/total)}%"></div></div><strong>${num(counts[k]||0,0)}</strong></div>`).join('');const rows=items.slice(-20).reverse().map(m=>[esc(short(m.message_id||'—',22)),esc(short(m.source||m.sender||'—',20)),esc(short(m.target||m.receiver||'—',20)),`<span class="reason-chip ${String(m.policy_action||m.action)==='DROP'?'muted-chip':''}">${esc(m.policy_action||m.action||'UNKNOWN')}</span>`,esc(m.reduction_ratio!=null?pct(m.reduction_ratio):m.bytes!=null?`${num(m.bytes,0)} B`:'—')]);const sparse=bench?.modes?.mosaic_sparse||{},full=bench?.modes?.full_mesh||{};const benchCard=bench?`<div class="deep-card"><h4>v1.9.0 受控低熵 Replay</h4><p>这是发布包基准，不冒充当前 Run 通信。相同捕获消息集只改变 fan-out 路由方式。</p><div class="deep-metrics">${deepMetric('Full Mesh tx',num(full.transmissions_replay,0))}${deepMetric('MOSAIC Sparse tx',num(sparse.transmissions_replay,0))}${deepMetric('Tx reduction',`${num(sparse.transmission_reduction_vs_full_mesh_pct,1)}%`)}${deepMetric('Byte reduction',`${num(sparse.byte_reduction_vs_full_mesh_pct,1)}%`)}</div><small>${esc(release.source||'packaged benchmark')}</small></div>`:'';el.innerHTML=`<div class="deep-card math-card"><h4>低熵通信决策链</h4><div class="algorithm-chain"><span>KnowledgeDigest</span><b>→</b><span>Receiver-aware Δ</span><b>→</b><span>Content Hash Dedup</span><b>→</b><span>Decision Impact</span><b>→</b><span>TTL / Token Budget</span><b>→</b><span>SEND / MERGE / DEFER / DROP</span></div><p>只展示后端真实 MessagePolicy 决策；没有受控 baseline 时不凭空生成“节省 xx%”。</p></div>${benchCard}<div class="deep-card"><h4>当前 Run 通信策略分布</h4><div class="deep-bar-list">${bars}</div></div><div class="deep-card"><h4>当前 Run 最近通信决策</h4>${deepTable(['Message','From','To','Policy','Reduction / Size'],rows)}</div>`;}
function renderJudgeMemory(){const el=$('deepMemory'),meta=$('deepMemoryMeta');if(!el||!meta)return;const m=state.snapshot?.memory||{},release=state.control?.release_benchmarks?.memory_ablation||null,bench=release?.data||null;meta.textContent=`${num(m.record_count,0)} records · ${num(m.context_pack_count,0)} ContextPacks`;const layers=[['WORKING','Working Memory','当前 Goal、DAG 与任务上下文'],['EPISODIC','Episodic Memory','Run、失败与恢复经历'],['SEMANTIC','Semantic Memory','经验证事实、约束与知识'],['PROCEDURAL','Procedural Memory','工具过程、恢复模式与操作经验']];const full=bench?.modes?.full_history||{},ctx=bench?.modes?.context_pack||{};const benchCard=bench?`<div class="deep-card"><h4>v1.9.0 Memory Ablation</h4><p>发布包受控实验，与当前 Run 分开；same final task + same history。Token 只标 ESTIMATED。</p><div class="deep-metrics">${deepMetric('Full History',`${num(full.estimated_tokens,0)} EST.`)}${deepMetric('ContextPack',`${num(ctx.estimated_tokens,0)} EST.`)}${deepMetric('Key-fact recall',`${num(ctx.key_fact_recall_pct,1)}%`)}${deepMetric('Estimated reduction',`${num(bench.context_reduction_vs_full_history_pct_estimated,2)}%`)}</div><small>${esc(release.source||'packaged benchmark')}</small></div>`:'';el.innerHTML=`<div class="memory-layer-grid">${layers.map(x=>`<div class="memory-layer"><span class="layer-id">${x[0]}</span><h4>${x[1]}</h4><p>${x[2]}</p></div>`).join('')}</div><div class="deep-card math-card"><h4>Memory Ranking</h4><div class="math-block">Score = 0.26R<sub>task</sub> + 0.16R<sub>evidence</sub> + 0.18I + 0.10C + 0.10R<sub>time</sub> + 0.06N + 0.14S + B<sub>verified</sub></div><div class="math-block small">R<sub>time</sub> = e<sup>−age/86400</sup></div><p>权重用于说明代码中的选择逻辑；最终选择数量与 token estimate 仍以当前 Snapshot 为准。</p></div>${benchCard}<div class="deep-card"><h4>当前 Run ContextPack 选择结果</h4><p>Estimated Context Token 与真实 Provider API usage 严格分开。</p><div class="deep-metrics">${deepMetric('Memory records',num(m.record_count,0))}${deepMetric('ContextPacks',num(m.context_pack_count,0))}${deepMetric('Full history',m.full_history_token_estimate!=null?`${num(m.full_history_token_estimate,0)} EST.`:'—')}${deepMetric('Selected context',m.context_pack_token_estimate!=null?`${num(m.context_pack_token_estimate,0)} EST.`:'—')}${deepMetric('Estimated reduction',m.token_reduction_estimate!=null?pct(m.token_reduction_estimate):'—')}${deepMetric('Real API tokens',state.snapshot?.authenticity?.api_usage?.token_status==='measured_api_usage'?num(state.snapshot.authenticity.api_usage.total_tokens,0):'INSUFFICIENT DATA')}</div></div>`;}
function renderJudgeVerifier(){const el=$('deepVerifier'),meta=$('deepVerifierMeta');if(!el||!meta)return;const s=state.snapshot||{},r=s.run||{},events=s.events||[],ver=events.filter(e=>eventType(e)==='TASK_VERIFIED'),tool=events.filter(e=>eventType(e)==='TOOL_EXECUTED'),ev=s.evidence?.items||[],evMap=new Map(ev.map(x=>[String(x.evidence_id),x]));meta.textContent=`${ver.length} TASK_VERIFIED · ${ev.length||r.evidence_count||0} evidence`;const rows=ver.slice(-20).reverse().map(v=>{const vv=v.payload?.verification||{},preds=vv.predicate_results||[],ids=v.payload?.evidence_ids||vv.evidence_refs||[],hashes=ids.map(id=>evMap.get(String(id))?.hash||evMap.get(String(id))?.digest).filter(Boolean);const predText=preds.length?preds.map(p=>`${p.passed===true?'✓':'✕'} ${p.predicate}`).join('<br>'):'—';return [esc(short(eventTask(v),28)),`<span class="reason-chip ${v.payload?.passed===true?'ok-chip':'fail-chip'}">${v.payload?.passed===true?'PASS':'FAIL'}</span>`,predText,hashes.length?hashes.map(h=>`<code>${esc(short(h,18))}</code>`).join('<br>'):'—',esc(vv.verifier||v.actor_id||'verifier')];});el.innerHTML=`<div class="verify-chain"><div class="verify-step"><span class="step-no">01</span><strong>Execution</strong><small>${tool.length} TOOL_EXECUTED events</small></div><div class="verify-step"><span class="step-no">02</span><strong>Evidence</strong><small>${ev.length||r.evidence_count||0} content-addressed items</small></div><div class="verify-step"><span class="step-no">03</span><strong>Predicates</strong><small>deterministic first; semantic only when required</small></div><div class="verify-step"><span class="step-no">04</span><strong>Independent Verdict</strong><small>${ver.filter(e=>e.payload?.passed===true).length} PASS / ${ver.filter(e=>e.payload?.passed===false).length} FAIL</small></div></div><div class="deep-card"><h4>Predicate → Evidence SHA256 → Verdict</h4><p>每行直接来自 TASK_VERIFIED + EvidenceStore；不接受 Agent 自报完成作为最终验收。</p>${deepTable(['Task','Verdict','Predicate checks','Evidence SHA256','Verifier'],rows)}</div>`;}
function renderJudgeRecovery(){const el=$('deepRecovery'),meta=$('deepRecoveryMeta');if(!el||!meta)return;const rec=state.snapshot?.recovery||{},all=deepEventsFor(),types=['FAULT_INJECTED','TOPOLOGY_REBUILT','TASK_ASSIGNED','TASK_RECOVERED','TASK_REPLANNED','RECOVERY_PLANNED','REPLAN_REQUIRED','ROLLBACK_REQUIRED','ROLLBACK_EXECUTED','SAFE_STOP_TRIGGERED','EVIDENCE_INVALIDATION_RECOVERY'];const events=(rec.events&&rec.events.length)?rec.events:all.filter(e=>types.includes(eventType(e)));meta.textContent=`${num(events.length,0)} adaptation / recovery events`;if(!events.length){el.innerHTML=deepEmpty('当前 Run 没有恢复事件','注入节点失效后会展示 FAULT_INJECTED → TOPOLOGY_REBUILT → 后续 Assignment；RecoveryEngine 的 retry/rollback 仍单独保留，不伪造成同一语义。');return;}el.innerHTML=`<div class="deep-card"><h4>Adaptation / Recovery timeline</h4><p>动态拓扑适应与 RecoveryEngine 恢复分开标记，避免把“重新路由”冒充“重试恢复”。</p><div class="recovery-timeline">${events.slice(-40).map(e=>`<div class="recovery-event"><div class="time">${esc(ts(e.timestamp||e.occurred_at))}</div><div class="rail"></div><div class="body"><strong>${esc(eventType(e))}</strong><span>${esc(eventTask(e)||e.actor_id||'run-level')} · ${esc(short(e.payload?.reason||e.payload?.control_semantics||e.payload?.action||'authoritative event',110))}</span></div></div>`).join('')}</div></div>`;}
function renderJudgeLabSummary(){const el=$('deepLabSummary');if(!el)return;const jobs=state.control?.experiment_jobs||[],results=state.control?.experiment_results||[],release=state.control?.release_benchmarks||{},benchJobs=jobs.filter(j=>j.kind==='benchmark');const byLabel=name=>results.find(x=>String(x.label||'').includes(name))?.data||release[name]?.data||null;const sourceFor=name=>results.find(x=>String(x.label||'').includes(name))?'本次 Experiment Job':release[name]?.source?'v1.9.0 发布包基准':'无结果';const topo=byLabel('topology_replay'),mem=byLabel('memory_ablation'),sched=byLabel('scheduler_ablation'),long=byLabel('long_horizon'),split=byLabel('split_inference_reference');const topoSparse=topo?.modes?.mosaic_sparse||{},memCtx=mem?.modes?.context_pack||{},memFull=mem?.modes?.full_history||{},ort=sched?.modes?.ortools||{};const cards=[['Topology replay',topo?`${num(topoSparse.transmissions_replay,0)} tx · ${num(topoSparse.transmission_reduction_vs_full_mesh_pct,1)}% vs full mesh`:'待运行',`${sourceFor('topology_replay')} · same-message-set replay`],['Memory ablation',mem?`${num(memFull.estimated_tokens,0)} → ${num(memCtx.estimated_tokens,0)} EST. · recall ${num(memCtx.key_fact_recall_pct,1)}%`:'待运行',`${sourceFor('memory_ablation')} · token=estimate`],['Scheduler ablation',sched?(ort.available?`OR-Tools cost ${num(ort.scheduler_objective_total_cost,4)}`:'OR-Tools unavailable'):'待运行',`${sourceFor('scheduler_ablation')} · same tasks / registry / weights / capacities`],['Long horizon',long?`${num(long.achieved_event_count_measured,0)} events · ${num(long.completed_task_count_measured,0)}/${num(long.total_task_count_measured,0)} tasks`:'待运行',`${sourceFor('long_horizon')} · authoritative EventStore`],['Split inference',split?(split.verified_equivalent?`equivalent · ${num(split.activation_payload_bytes_measured,0)} B activation`:'not equivalent'):'待运行',`${sourceFor('split_inference_reference')} · reference MLP, not LLM layer split`]];el.innerHTML=`<div class="deep-card"><h4>实验展示原则</h4><p>目的 → 控制变量 → Baseline → MOSAIC → 指标 → 原始 JSON。优先展示本次成功 Experiment Job；若尚未运行，则展示 v1.9.0 包内重新生成的受控 benchmark，并明确区分。</p><div class="deep-metrics">${deepMetric('Experiment jobs',num(jobs.length,0))}${deepMetric('Benchmark succeeded',num(benchJobs.filter(j=>j.status==='SUCCEEDED').length,0))}${deepMetric('Packaged benchmarks',num(Object.keys(release).length,0))}${deepMetric('Truth boundary','MEASURED / ESTIMATED separated')}</div></div><div class="benchmark-result-grid">${cards.map(c=>`<div class="deep-card"><h4>${esc(c[0])}</h4><div class="benchmark-value">${esc(c[1])}</div><p>${esc(c[2])}</p></div>`).join('')}</div>`;}
function renderJudgeLineageSummary(){const el=$('deepLineageSummary');if(!el)return;const s=state.snapshot||{},line=s.data_lineage||[],contracts=s.state_machine?.display_status_contracts||[];el.innerHTML=`<div class="deep-card"><h4>Traceability contract</h4><p>每个状态、数字与图形必须追溯到 API 字段、EventStore 事件或明确派生公式。</p><div class="deep-metrics">${deepMetric('Lineage fields',num(line.length,0))}${deepMetric('State contracts',num(contracts.length,0))}${deepMetric('Events',num((s.events||[]).length,0))}${deepMetric('Evidence',num(s.run?.evidence_count||0,0))}</div></div>`;}
function renderJudgeDeep(){if(state.view!=='judge')return;renderJudgePanorama();if(state.deep==='dag')renderJudgeDag();else if(state.deep==='scheduler')renderJudgeScheduler();else if(state.deep==='collaboration')renderJudgeCollaboration();else if(state.deep==='communication')renderJudgeCommunication();else if(state.deep==='memory')renderJudgeMemory();else if(state.deep==='verifier')renderJudgeVerifier();else if(state.deep==='recovery')renderJudgeRecovery();else if(state.deep==='lab')renderJudgeLabSummary();else if(state.deep==='lineage')renderJudgeLineageSummary();}
function renderCurrentView(){renderChrome();switch(state.view){case'workspace':renderWorkspace();break;case'tasks':renderTasks();break;case'agents':renderAgents();break;case'deliverables':renderDeliverables();break;case'settings':renderSettings();break;case'observatory':renderObservatory();break;case'lab':renderLab();break;case'judge':renderJudge();renderJudgeDeep();break;case'lineage':renderLineage();break;default:renderWorkspace();}}
function renderAll(){renderChrome();renderWorkspace();renderTasks();renderAgents();renderDeliverables();renderSettings();renderObservatory();renderLab();renderJudge();renderLineage();}

async function controlAction(url,payload,viewAfter='tasks'){try{const data=await postJSON(url,payload);if(data.result?.run_id)state.runId=data.result.run_id;await refresh();setView(viewAfter);toast('后端已接受操作；状态将以真实运行结果更新');}catch(e){toast(`后端拒绝操作：${e.message}`,true);}}

$('nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view);});document.body.addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)setView(b.dataset.go);const d=e.target.closest('[data-deep]');if(d)setDeepPanel(d.dataset.deep);});
$('judgeModeBtn').onclick=()=>setView('judge');$('refreshBtn').onclick=()=>{state.paused=false;$('pauseBtn').textContent='暂停刷新';refresh();};$('pauseBtn').onclick=()=>{state.paused=!state.paused;$('pauseBtn').textContent=state.paused?'恢复刷新':'暂停刷新';};$('runSelector').onchange=e=>{state.runId=e.target.value||null;refresh();};
$('startCustomBtn').onclick=()=>controlAction('/api/control/start-custom',{goal:$('goalInput').value},'workspace');$('goalInput').addEventListener('input',updateActionAvailability);$('stopJobBtn').onclick=()=>controlAction('/api/control/stop',{job_id:state.control?.active_job?.job_id||null},'tasks');$('refreshArtifactsBtn').onclick=loadArtifacts;$('providerSelect').onchange=onProviderChanged;$('saveProviderBtn').onclick=saveProvider;$('testProviderBtn').onclick=testProvider;$('saveEndpointBtn').onclick=saveEndpoint;$('testEndpointBtn').onclick=()=>testEndpoint();$('newEndpointBtn').onclick=clearEndpointForm;$('clearProviderKeyBtn').onclick=clearProviderKey;$('saveAgentBtn').onclick=saveAgent;$('newAgentBtn').onclick=clearAgentForm;$('closeArtifactModal').onclick=()=>$('artifactModal').classList.add('hidden');$('artifactModal').onclick=e=>{if(e.target===$('artifactModal'))$('artifactModal').classList.add('hidden');};

function startRuntimeStream(){
  if(state.stream||!('EventSource' in window)||!/^https?:$/.test(location.protocol))return;
  try{const stream=new EventSource('/api/stream');state.stream=stream;stream.addEventListener('runtime',()=>refresh());stream.onerror=()=>{try{stream.close();}catch(_){}state.stream=null;setTimeout(startRuntimeStream,4500);};}catch(_){state.stream=null;}
}
setView('workspace');loadBase().then(()=>refresh()).catch(()=>refresh());startRuntimeStream();setInterval(()=>{if(!state.stream)refresh();},2500);
